inbound.set-body:
@{
            var body = context.Request.Body.As(preserveContent: false);
            var messages = (JArray)(body["messages"] ?? new JArray());
            var contents = new JArray();
            foreach (var m in messages) {
                var role = (string)m["role"];
                var geminiRole = role == "assistant" ? "model" : "user";
                contents.Add(new JObject(
                    new JProperty("role", geminiRole),
                    new JProperty("parts", new JArray(new JObject(new JProperty("text", (string)m["content"]))))
                ));
            }
            return new JObject(
                new JProperty("contents", contents),
                new JProperty("generationConfig", new JObject(
                    new JProperty("maxOutputTokens", (int?)body["max_tokens"] ?? 1024),
                    new JProperty("temperature", (double?)body["temperature"] ?? 0.7)
                ))
            ).ToString();
        }
